WITH flattened AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS key, v), flattened_attrs AS (SELECT id, host, log_ts, status_code, CAST((status_code & 1) != 0 AS INT) AS flag_bit1, SHIFTRIGHT(status_code, 2) AS status_code_high FROM flattened WHERE host IN ('h1', 'h2')), cleaned AS (SELECT id, host, log_ts, status_code, flag_bit1, status_code_high, status_code_high + flag_bit1 AS status_code_high_plus_flag_bit1 FROM flattened_attrs WHERE log_ts > DATE '2025-06-01' AND flag_bit1 >= 1), metrics AS (SELECT *, STDDEV_SAMP(status_code_high_plus_flag_bit1) OVER (PARTITION BY TO_DATE(log_ts), host) AS log_ts_to_date_stddev_samp_status_code_high_plus_flag_bit1 FROM cleaned WHERE status_code_high <= 1) SELECT host, CASE WHEN status_code_high_plus_flag_bit1 >= 72 THEN 'HIGH' ELSE 'LOW' END AS status_code_high_plus_flag_bit1_tier, APPROX_PERCENTILE(flag_bit1, 0.9) AS flag_bit1_p90, COUNT(*) AS cnt, SORT_ARRAY(COLLECT_SET(host)) AS host_list, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS span_minutes, COUNT(*) AS cnt_2, COUNT(*) FILTER (WHERE host = 'h3') AS h3_rows, GROUPING_ID() AS gid FROM metrics GROUP BY GROUPING SETS ((host, CASE WHEN status_code_high_plus_flag_bit1 >= 72 THEN 'HIGH' ELSE 'LOW' END), (host)) ORDER BY cnt DESC NULLS FIRST;
